from __future__ import unicode_literals

import os
import re
import shutil

from functools import partial
from zipfile import ZipFile
from subprocess import call

from ute_common_util.context import NewSession
from ute_fsmaccess import ute_fsmaccess


class Scfd(object):

    def get_all_from_enb(self, enb_ip='192.168.255.1', partition='active', output_dir='.'):
        """Downloads all SDFD files from given partition of eNB to output_dir."""
        partition_path = '/ffs/run/' if partition == 'active' else '/ffs/stb/'
        enb_session = ute_fsmaccess()
        setup_method = partial(enb_session.setup_enb_fsm_access, host=enb_ip)
        with NewSession(enb_session, setup=setup_method,
                        teardown=enb_session.teardown_enb_fsm_access) as new_enb_session:
            scfd_dir = self._get_scfd_dir(new_enb_session, partition_path)
            scp_cmd = 'sshpass -p oZPS0POrRieRtu scp toor4nsn@192.168.255.129:{} {}'
            call(scp_cmd.format(os.path.join(scfd_dir, 'SCFD*.txt'), output_dir), shell=True)

    def _get_scfd_dir(self, new_enb_session, partition_path):
        scfd_file_path = new_enb_session.execute_command_on_enb("find {} -name SCFD*txt -type f | head -n 1".format(partition_path), shell=True)
        return os.path.dirname(os.path.abspath(scfd_file_path))

    def get_all_from_enb_sw_zip(self, sw_zip_path, output_dir='.'):
        """Extracts all SDFD files from given eNB SW package to output_dir. Both puttibatti- and BTSSM-based packages are supported."""
        sw_zip = ZipFile(sw_zip_path)
        scfd_paths = [path for path in sw_zip.namelist() if re.match('.*SCFD.*.txt$', path)]
        for scfd_path in scfd_paths:
            self._extract_to_dir(sw_zip, scfd_path, output_dir)

    def _extract_to_dir(self, zip, path_in_zip, output_dir):
        if '#1_' in path_in_zip:
            self._extract_fragmented_file(zip, path_in_zip, output_dir)
        elif '#' not in path_in_zip:
            self._extract_normal_file(zip, path_in_zip, output_dir)

    def _extract_normal_file(self, zip, path_in_zip, output_dir):
        dest_file_name = os.path.join(output_dir, os.path.basename(path_in_zip))
        with zip.open(path_in_zip) as source_file, open(dest_file_name, 'wb') as dest_file:
            shutil.copyfileobj(source_file, dest_file)

    def _extract_fragmented_file(self, zip, first_fragment_path, output_dir):
        basename = os.path.basename(first_fragment_path).replace('#1', '')
        dest_file_name = os.path.join(output_dir, basename)
        zip_contents = zip.namelist()
        with open(dest_file_name, 'wb') as dest_file:
            fragment_path = first_fragment_path
            index = 1
            while fragment_path in zip_contents:
                with zip.open(fragment_path) as source_file:
                    shutil.copyfileobj(source_file, dest_file)
                index += 1
                fragment_path = first_fragment_path.replace('#1', '#' + str(index))
